/// to Day 365, blending classical allusions, math/tech trivia, and memes.
library;

/// One single-project check-in day milestone with allusion/meme lore.
class SingleProjectMilestone {
  const SingleProjectMilestone({
    required this.days,
    required this.title,
    required this.lore,
    required this.iconKey,
  });

  final int days;
  final String title;
  final String lore;
  final String iconKey;

  String get id => 'single_$days';
}

/// Filter stage tabs for browsing the full single-project catalog.
class SingleMilestoneStage {
  const SingleMilestoneStage({
    required this.id,
    required this.label,
    this.minDays,
    this.maxDays,
    this.unlockedOnly = false,
  });

  final String id;
  final String label;
  final int? minDays;
  final int? maxDays;
  final bool unlockedOnly;
}

